/* Big-number Fibonacci (base 1e9 limbs) so large N works too. */
int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s N\n", argv[0]); return 1; }
    long n = strtol(argv[1], NULL, 10);
    if (n < 0) { fprintf(stderr, "N must be >= 0\n"); return 1; }
    size_t cap = (size_t)(n * 0.20898764 / 9) + 4;
    unsigned int *a = calloc(cap, sizeof *a), *b = calloc(cap, sizeof *b);
    size_t len = 1;
    a[0] = 0; b[0] = 1; /* a = F(i), b = F(i+1) */
    for (long i = 0; i < n; i++) {
